Rewrite the following GNU C++ code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include <cmath>
#include <ctime>
#include <cctype>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cassert>
#include <functional>
#include <algorithm>
#include <iostream>
#include <numeric>
#include <iomanip>
#include <sstream>
#include <bitset>
#include <string>
#include <vector>
#include <stack>
#include <queue>
#include <list>
#include <set>
#include <map>
using namespace std;

#define debug(args...) fprintf(stderr,args)
#define foreach(_it,_v) for(typeof(_v.begin()) _it = _v.begin(); _it != _v.end(); ++_it)

typedef long long lint;
typedef pair<int,int> pii;
typedef pair<lint,lint> pll;

const int INF = 0x3f3f3f3f;
const lint LINF = 0x3f3f3f3f3f3f3f3fll;
const int MAXN = 20;
const int MAXV = 2*MAXN*MAXN;

char m1[MAXN][MAXN], m2[MAXN][MAXN];
int inf_time[MAXN][MAXN];
int n,t;

int dx[] = {1,0,-1,0};
int dy[] = {0,1,0,-1};

void bfs(int x,int y) {
    for(int a=0;a<n;++a)
        for(int b=0;b<n;++b)
            inf_time[a][b] = INF;
    inf_time[x][y] = 0;
    queue<pii> fila;
    fila.push(pii(x,y));
    while(!fila.empty()) {
        int cx = fila.front().first, cy = fila.front().second;
        fila.pop();
        for(int a=0;a<4;++a) {
            int nx = cx+dx[a], ny = cy+dy[a];
            if(nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if('0' <= m1[nx][ny] && m1[nx][ny] <= '9' && inf_time[nx][ny] == INF) {
                inf_time[nx][ny] = inf_time[cx][cy] + 1;
                fila.push(pii(nx,ny));
            }
        }
    }
}

bool foi[MAXN][MAXN];

vector<int> adj[MAXV];
int cap[MAXV][MAXV];

inline void insert_edge(int u,int v,int c) {
    adj[u].push_back(v);
    adj[v].push_back(u);
    cap[u][v] = c;
    cap[v][u] = 0;
}

int tempo[MAXN][MAXN];
bool dinic_foi[MAXV];
int dist[MAXV];

bool dinic_bfs(int s,int t) {
    memset(dist,-1,sizeof(dist));
    dist[s] = 0;
    queue<int> fila;
    fila.push(s);
    while(!fila.empty() && dist[t] == -1) {
        int v = fila.front();
        fila.pop();
        foreach(nxt,adj[v]) {
            if(!cap[v][*nxt] || dist[*nxt] != -1) continue;
            dist[*nxt] = dist[v] + 1;
            fila.push(*nxt);
        }
    }
    return dist[t] != -1;
}

void bfs2(int px,int py) {
    memset(tempo,INF,sizeof(tempo));
    tempo[px][py] = 0;
    if('1' <= m2[px][py] && m2[px][py] <= '9')
        insert_edge(n*px+py, n*n+n*px+py,INF);
    queue<pii> fila;
    fila.push(pii(px,py));
    while(!fila.empty()) {
        int x = fila.front().first, y = fila.front().second;
        fila.pop();
        for(int a=0;a<4;++a) {
            int nx = x+dx[a], ny = y+dy[a];
            if(nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if(tempo[nx][ny] != INF) continue;
            if(!('0' <= m1[nx][ny] && m1[nx][ny] <= '9')) continue;
            if(tempo[x][y] + 1 <= min(inf_time[nx][ny]-1,t)) {
                tempo[nx][ny] = tempo[x][y] + 1;
                fila.push(pii(nx,ny));
            }
            if(tempo[x][y] + 1 <= min(inf_time[nx][ny],t) && '1' <= m2[nx][ny] && m2[nx][ny] <= '9')
                insert_edge(n*px+py,n*n + n*nx + ny, INF);
        }
    }
}

int dinic_dfs(int v,int t,int flow) {
    if(v == t) return flow;
    dinic_foi[v] = 1;
    foreach(nxt,adj[v]) {
        if(!cap[v][*nxt] || dinic_foi[*nxt] || dist[*nxt] != dist[v] + 1) continue;
        int got = dinic_dfs(*nxt,t,min(flow,cap[v][*nxt]));
        if(got) {
            cap[v][*nxt] -= got;
            cap[*nxt][v] += got;
            return got;
        }
    }
    return 0;
}    

int dinic(int s,int t) {
    int ret = 0, got;
    while(dinic_bfs(s,t)) {
        memset(dinic_foi,0,sizeof(dinic_foi));
        while(got = dinic_dfs(s,t,INF)) ret += got;
    }
    return ret;
}

int main() {
    scanf("%d%d",&n,&t);
    int ix,iy;
    int s = MAXV-2, t = MAXV-1;
    for(int a=0;a<n;++a) {
        for(int b=0;b<n;++b) {
            scanf(" %c",&m1[a][b]);
            if(m1[a][b] == 'Z') {
                ix = a; iy = b;
            }
            else if('1' <= m1[a][b] && m1[a][b] <= '9')
                insert_edge(s,a*n+b,m1[a][b]-'0');
        }
    }
    bfs(ix,iy);
    for(int a=0;a<n;++a) {
        for(int b=0;b<n;++b) {
            scanf(" %c",&m2[a][b]);
            if('1' <= m2[a][b] && m2[a][b] <= '9')
                insert_edge(n*n + a*n+b,t,m2[a][b]-'0');
        }
    }
    for(int a=0;a<n;++a)
        for(int b=0;b<n;++b)
            if('1' <= m1[a][b] && m1[a][b] <= '9')
                bfs2(a,b);
    printf("%d\n",dinic(s,t));    
    return 0;
}

